{"content":"import fontforge

def verify_glyphs(font_path, glyph_names):
    try:
        font = fontforge.open(font_path)
        for name in glyph_names:
            if name in font:
                # Basic check: verify the glyph is not empty
                # An empty glyph usually has no outlines
                glyph = font[name]
                if not glyph.isEmpty():
                    print(f"Verified: {name} exists and is not empty in {font_path}")
                else:
                    print(f"Warning: {name} exists but appears empty")
            else:
                print(f"FAILED: {name} NOT found in {font_path}")
        font.close()
    except Exception as e:
        print(f"Error opening font: {e}")

if __name__ == "__main__":
    verify_glyphs("/home/luffy/.local/share/fonts/CustomFont.ttf", ["parenleft", "parenright", "braceleft", "braceright"])
